mapper.insert:
/* RefreshTokenMapper.insertRefreshToken */
INSERT INTO refresh_token (user_no, token_hash, device_info, ip_address, expires_at, created_at)
VALUES (#{userNo}, #{tokenHash}, #{deviceInfo}, #{ipAddress}, #{expiresAt}, #{createdAt})

mapper.select:
/* RefreshTokenMapper.findByTokenHash */
SELECT id, user_no, token_hash, device_info, ip_address, expires_at, created_at
FROM refresh_token
WHERE token_hash = #{tokenHash}
  AND expires_at > NOW()

mapper.delete:
/* RefreshTokenMapper.deleteByTokenHash */
DELETE FROM refresh_token
WHERE token_hash = #{tokenHash}

/* RefreshTokenMapper.deleteByUserNo */
DELETE FROM refresh_token
WHERE user_no = #{userNo}

/* RefreshTokenMapper.deleteExpired */
DELETE FROM refresh_token
WHERE expires_at < NOW()
